import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

interface OpStateAttrs { "data-op"?: string; "data-mark"?: string; "data-role"?: string }
interface ScalarFrame { structure: "scalar"; values: Record<string, number | string>; ops?: Record<string, { op: string }> }

function scalarVarState(frame: ScalarFrame, name: string): OpStateAttrs {
  const op = frame.ops?.[name];
  return op ? { "data-op": op.op } : {};
}
export function ScalarView({ frame = { structure: "scalar", values: { i: 0, sum: 42, done: "false" }, ops: { sum: { op: "write" } } } }: { frame?: ScalarFrame }) {
  const names = Object.keys(frame.values).sort();

  return (
    <Box className="scalar-view" role="group" aria-label="scalar state">
      {names.length === 0 ? (
        <Box className="scalar-empty" aria-label="empty">
          (no variables)
        </Box>
      ) : (
        names.map((name) => (
          <Box
            key={name}
            className="scalar-chip"
            role="group"
            aria-label={name}
            {...scalarVarState(frame, name)}
            title={`${name} = ${frame.values[name]}`}
          >
            <Text as="span" className="scalar-name mono">
              {name}
            </Text>
            <Text as="span" className="scalar-val mono">
              {frame.values[name]}
            </Text>
          </Box>
        ))
      )}
    </Box>
  );
}
